<?php

declare(strict_types=1);

namespace App\Connections\Calls;

use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use App\AgentRequests\Values\CallAccepted;

/**
 * The signed calls of Connections, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class ConnectionCalls
{
    public function __construct(private CallSender $sender) {}

    public function cancelProjectCommand(
        string $requestKey,
    ): CallAccepted {
        return $this->sender->send(CancelProjectCommandCall::from([
            'requestKey' => $requestKey,
        ]));
    }

    public function readProjectCommandStatus(
        string $bindingId,
        string $requestKey,
    ): ProjectCommandStatus {
        return $this->sender->send(ReadProjectCommandStatusCall::from([
            'bindingId' => $bindingId,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $argv
     */
    public function runProjectCommand(
        string $bindingId,
        array $argv,
        CallKey $requestKey = new CallKey(),
        string|null $stdin = null,
    ): ProjectCommandFrames {
        return $this->sender->send(RunProjectCommandCall::from([
            'bindingId' => $bindingId,
            'argv' => $argv,
            'requestKey' => $requestKey,
            'stdin' => $stdin,
        ]));
    }
}
